// Minimal react stand-in with a single-component hook runtime, enough to render
// a plugin component function offline and catch ReferenceErrors/typos.
let hooks = []
let cursor = 0

export function useState(initial) {
  const slot = cursor++

  if (hooks[slot] === undefined) {
    hooks[slot] = typeof initial === 'function' ? initial() : initial
  }

  const set = next => {
    hooks[slot] = typeof next === 'function' ? next(hooks[slot]) : next
  }

  return [hooks[slot], set]
}

export function useEffect(effect) {
  const slot = cursor++

  if (!hooks[slot]) {
    hooks[slot] = true
    effect()
  }
}

export const useMemo = fn => fn()
export const useCallback = fn => fn
export const useRef = initial => ({ current: initial ?? null })
export const Fragment = Symbol('Fragment')

export function renderComponent(component, props = {}) {
  hooks = []
  cursor = 0

  return component(props)
}
